draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw apple
  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.fill();
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.stroke();

  // draw leaf
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 70, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.stroke();

  // draw stick figure
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2 + 100, H/2, 20, 0, 2 * Math.PI); // head
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 20);
  ctx.lineTo(W/2 + 100, H/2 + 100); // body
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 50);
  ctx.lineTo(W/2 + 80, H/2 + 80); // arm
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 50);
  ctx.lineTo(W/2 + 120, H/2 + 80); // arm
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 100);
  ctx.lineTo(W/2 + 90, H/2 + 130); // leg
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 100);
  ctx.lineTo(W/2 + 110, H/2 + 130); // leg
  ctx.stroke();

  // animate stick figure eating apple
  ctx.save();
  ctx.translate(W/2 + 100, H/2 + 20);
  ctx.rotate(Math.sin(t) * 0.1);
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.lineTo(0, -20); // arm eating
  ctx.stroke();
  ctx.restore();

  ctx.restore();
}
